public enum CollectionBehavior
	/// Default implementation of <see cref="T:Xunit.v3.ICollectionBehaviorAttribute" />.
	public sealed class CollectionBehaviorAttribute : Attribute, ICollectionBehaviorAttribute
		/// Initializes a new instance of the <see cref="T:Xunit.CollectionBehaviorAttribute" /> class.
		/// Uses the default collection behavior (<see cref="F:Xunit.CollectionBehavior.CollectionPerClass" />).
		public CollectionBehaviorAttribute()
		/// Initializes a new instance of the <see cref="T:Xunit.CollectionBehaviorAttribute" /> class
		/// <param name="collectionBehavior">The collection behavior for the assembly.</param>
		public CollectionBehaviorAttribute(CollectionBehavior collectionBehavior)
			CollectionFactoryType = collectionBehavior switch
				CollectionBehavior.CollectionPerClass => typeof(CollectionPerClassTestCollectionFactory), 
				CollectionBehavior.CollectionPerAssembly => typeof(CollectionPerAssemblyTestCollectionFactory), 
		/// Initializes a new instance of the <see cref="T:Xunit.CollectionBehaviorAttribute" /> class
		public CollectionBehaviorAttribute(Type collectionFactoryType)
	public interface ICollectionBehaviorAttribute
	/// End users specify the desired test collection factory by applying <see cref="T:Xunit.CollectionBehaviorAttribute" />
	/// (or any attribute that implements <see cref="T:Xunit.v3.ICollectionBehaviorAttribute" />) at the assembly level.
		ICollectionBehaviorAttribute? CollectionBehavior { get; }
			ICollectionBehaviorAttribute collectionBehavior = testAssembly.CollectionBehavior;
			TestCollectionFactory = collectionFactory ?? ExtensibilityPointFactory.GetXunitTestCollectionFactory(collectionBehavior?.CollectionFactoryType, testAssembly) ?? new CollectionPerClassTestCollectionFactory(testAssembly);
<exited with exit code 0>

